"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

// Divider: generated by UIX from the design system. Same variants and sizes as the Figma component.

export interface DividerProps extends React.HTMLAttributes<HTMLDivElement> {
  type?: "solid" | "dashed" | "with-label" | "with-icon";
  /** Text in the middle of the "with-label" divider. */
  label?: React.ReactNode;
  /** Icon in the middle of the "with-icon" divider. */
  icon?: React.ReactNode;
}

const Divider = React.forwardRef<HTMLDivElement, DividerProps>(({ className, type = "solid", label, icon, ...props }, ref) => {
  if (type === "solid") {
    return (
      <div ref={ref} data-slot="divider" data-kind="track" role="separator" className={cn("skin-quiet h-px w-full bg-line-default", className)} {...props} />
    );
  }
  if (type === "dashed") {
    return (
      <div ref={ref} data-slot="divider" data-kind="track" role="separator" className={cn("skin-quiet w-full border-t border-dashed border-line-default", className)} {...props} />
    );
  }
  if (type === "with-label") {
    return (
      <div ref={ref} data-slot="divider" data-kind="track" role="separator" className={cn("skin-quiet flex w-full items-center gap-3", className)} {...props}>
        <span aria-hidden className="h-px flex-1 bg-line-default" />
        <span className="text-label-small text-fg-tertiary">{label}</span>
        <span aria-hidden className="h-px flex-1 bg-line-default" />
      </div>
    );
  }
  if (type === "with-icon") {
    return (
      <div ref={ref} data-slot="divider" data-kind="track" role="separator" className={cn("skin-quiet flex w-full items-center gap-3", className)} {...props}>
        <span aria-hidden className="h-px flex-1 bg-line-default" />
        <span className="inline-flex text-icon-secondary [&_svg]:size-4">{icon}</span>
        <span aria-hidden className="h-px flex-1 bg-line-default" />
      </div>
    );
  }
  return <div ref={ref} data-slot="divider" data-kind="track" role="separator" className={cn("skin-quiet h-px w-full bg-line-default", className)} {...props} />;
});
Divider.displayName = "Divider";

export { Divider };
